BEGIN;

INSERT INTO public.categories (subject_id, name, color, sort_order)
SELECT s.id, '数学の部品箱', '#8b95c9', 8
FROM public.subjects s
WHERE s.slug = 'stats-basics'
ON CONFLICT (subject_id, name) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('stats9-q01', '数学の部品箱',
   '20問のクイズで15問正解した。正解率は何%か。',
   NULL::text,
   '["75%", "0.75%", "133%", "5%"]',
   0,
   '[0]',
   'single',
   '{"asked": "正解した問題の割合を「%」で出す方法。", "point": "割合は「部分 ÷ 全体」。%にするにはさらに100を掛ける。", "kid": "15問正解、全部で20問。15を20で割ると「割合」が出る。それを100倍すると見慣れた%になる。", "eg": "ケーキを10等分して3切れ食べたら、食べた割合は3÷10=0.3。これを100倍すると「30%食べた」と言える。%は「割合を100倍して見やすくしただけ」の数。", "terms": [["割合", "部分 ÷ 全体 で出す、全体を1としたときの大きさ"], ["%（パーセント）", "割合を100倍して表した単位。0.75なら75%"]], "think": "「15問中何問正解したか」をそのまま比べるのは、全体の問題数が違うテスト同士だと不公平になる。だから「割合」に直す。15÷20=0.75は「全体を1としたら0.75ぶん」という意味。0.75のままだと感覚がつかみにくいので、100を掛けて75%という見慣れた形にする。統計でこの後よく出てくる「確率」も、考え方はこの%と同じ「部分÷全体」。", "calc": "正解数  ÷  全体数\n  15   ÷   20   = 0.75\n0.75 × 100 = 75　←　100を掛けて%にする", "vs": "0.75%（=0.0075）は、100を掛け忘れた数。133%は分子と分母を逆にした（20÷15×100）。%の問題でまず疑うのは「100を掛けたか」「割る順番は合っているか」の2点。", "why_asked": "この後に出てくる確率・分散・信頼区間はすべて「部分÷全体」の考え方の応用。%の計算を体に入れておかないと、そこから先の式の意味が実感できなくなる。", "usecase": "テストの正答率、アンケートの回答率、工場製品の不良率など、日常のあらゆる「割合」の表現の土台。", "opt": ["正解。15÷20=0.75、これを100倍して75%。", "0.75は割合そのもの。100を掛けて%に直すのを忘れた値。", "20÷15×100の計算で、分子と分母を逆にしてしまった値。", "20−15=5を、そのまま%の答えだと勘違いした値。"], "viz": "<svg viewBox=\"0 0 340 125\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"20\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">20問中15問正解 → 75%</text><rect x=\"30\" y=\"55\" width=\"280\" height=\"26\" rx=\"3\" fill=\"#2a2f3f\"/><rect x=\"30\" y=\"55\" width=\"210\" height=\"26\" rx=\"3\" fill=\"#3b82f6\" opacity=\"0.7\"/><text x=\"135\" y=\"72\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">正解 15問</text><text x=\"275\" y=\"72\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">不正解5問</text><line x1=\"30\" y1=\"90\" x2=\"30\" y2=\"96\" stroke=\"#2a2f3f\"/><text x=\"30\" y=\"107\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">0%</text><line x1=\"240\" y1=\"90\" x2=\"240\" y2=\"96\" stroke=\"#2a2f3f\"/><text x=\"240\" y=\"107\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">75%</text><line x1=\"310\" y1=\"90\" x2=\"310\" y2=\"96\" stroke=\"#2a2f3f\"/><text x=\"310\" y=\"107\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">100%</text></svg>"}'),

  ('stats9-q02', '数学の部品箱',
   '平均60点のテストで56点だった。平均との差を、マイナスを使って表すとどうなるか。',
   NULL::text,
   '["-4", "4", "-116", "64"]',
   0,
   '[0]',
   'single',
   '{"asked": "「平均より少ない」を数でどう表すかという、マイナスの基本の使い方。", "point": "「自分の点数 − 平均」を計算する。平均より下なら答えはマイナスになる。", "kid": "56点は60点より4点足りない。「足りない」を数で表すときに使うのがマイナス。60より4小さいので−4。", "eg": "エレベーターで1階を0階とすると、地下1階は「−1階」と呼ぶ。地下は「下にある」ことを、マイナスの数1つで表している。テストの点も同じで、平均より下にあることを「マイナス」で表す。", "terms": [["マイナス（負の数）", "基準（この場合は平均）より小さいことを表す数"], ["偏差", "自分の値と平均の差。この−4がその第一歩"]], "think": "ふつうの引き算「56−60」を筆算のやり方どおりにやろうとすると戸惑う。考え方を変えて、「基準（60）からどれだけ動いたか」を見る。56は60より4小さい位置にあるので、動いた量は−4。プラスは基準より上、マイナスは基準より下、という「向き」の意味だと捉えると迷わない。", "calc": "点数    56\n平均    60\n差 = 56 − 60 = −4　←　平均より4小さい＝マイナス4", "vs": "「4」は60−56を計算した値で、符号（向き）が逆。平均より下なのでマイナスを付けるのが正しい。統計で「偏差」というとき、このマイナスの符号は「平均より下だった」という情報そのものなので、絶対に消してはいけない。", "why_asked": "この後の分散・標準偏差はすべて「平均との差」の積み重ねで計算する。差にマイナスが付くことを最初に体に入れておかないと、次に出てくる「2乗する理由」が腑に落ちない。", "usecase": "家計簿の「予算より使いすぎた／少なかった」、体温の「平熱より高い／低い」など、基準との差をプラスマイナスで表す場面全般。", "opt": ["正解。56−60=−4。平均より低いのでマイナスの符号が付く。", "60−56=4を計算した値。「平均より下」という向きのマイナスを付け忘れている。", "56−60を、引き算のつもりで足し算してしまった値（56+60=116の符号を反転しただけ）。", "平均60に4を足しただけの値。差の計算になっていない。"], "viz": "<svg viewBox=\"0 0 340 115\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"18\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\">平均60点を基準に見る</text><line x1=\"30\" y1=\"55\" x2=\"310\" y2=\"55\" stroke=\"#2a2f3f\" stroke-width=\"1.5\"/><line x1=\"170\" y1=\"49\" x2=\"170\" y2=\"61\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"170\" y=\"40\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\">平均60</text><circle cx=\"100\" cy=\"55\" r=\"4.5\" fill=\"#c47070\"/><text x=\"100\" y=\"78\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">56点</text><line x1=\"160\" y1=\"90\" x2=\"108\" y2=\"90\" stroke=\"#c47070\" stroke-width=\"1.3\"/><polygon points=\"108,90 117,86 117,94\" fill=\"#c47070\"/><text x=\"134\" y=\"103\" fill=\"#c47070\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">差は −4</text></svg>"}'),

  ('stats9-q03', '数学の部品箱',
   '前の問題で出た差「−4」を2乗する（同じ数を2回掛ける）と、答えはどうなるか。',
   NULL::text,
   '["16", "-16", "8", "-8"]',
   0,
   '[0]',
   'single',
   '{"asked": "マイナスの数どうしを掛けると、なぜプラスになるかという疑問への答え。", "point": "マイナス×マイナスはプラスになる。だから差を2乗すると、必ずプラスの数になる。", "kid": "−4を2乗するとは、−4を2回掛けること。（−4）×（−4）を計算すると16というプラスの数になる。マイナスどうしを掛けるとプラスになる、というのが算数のルール。", "eg": "向きを反対にする操作を「2回」やると、元の向きに戻る。テレビのリモコンで「反転」ボタンを2回押すと画面が元通りになるのと同じ。マイナスを掛けることは「向きを反対にする」操作なので、2回やると符号がプラスに戻る。", "terms": [["2乗", "同じ数を2回掛けること。4なら4×4"], ["マイナス×マイナス＝プラス", "負の数どうしを掛けると答えは正の数になるという規則"]], "think": "−4は「基準より4小さい」という向きを持った数。これを2乗するとは「その向きの操作を2回繰り返す」ということ。1回目の反転で向きがマイナスになり、2回目の反転で向きがまた反対になり、結局プラスに戻る。だから（−4）×（−4）=+16。この性質のおかげで、平均よりプラス側に離れていてもマイナス側に離れていても、2乗すればすべて同じプラスの数として扱える。", "calc": "  −4  ×  −4\n= (4×4) の符号を2回反転\n=  16 → 16 → +16　←　マイナス×マイナスでプラスに戻る", "vs": "−16は、符号の反転が1回で止まってしまった（4×4はできているが、マイナスが1つ残った）計算ミス。8や−8は「2乗」を「2倍」と混同した値で、そもそも掛け算の回数が違う。", "why_asked": "次のセットで出てくる「分散」は、平均との差（プラスもマイナスもある）をすべて2乗してから平均する。マイナス×マイナス＝プラスを知らないと、なぜ分散が2乗を使うのか、なぜ2乗すると全部プラスに揃うのかが理解できない。", "usecase": "分散・標準偏差の計算、誤差の大きさを符号なしで比べたいときの2乗誤差など、統計・機械学習のいたるところで使う。", "opt": ["正解。（−4）×（−4）=16。マイナスどうしの掛け算はプラスになる。", "4×4=16の計算はできているが、マイナスを1つ消し忘れた値。", "2乗ではなく「2倍」してしまった値（−4×2=−8の符号を反転）。", "−4を2倍しただけの値。2乗（同じ数を2回掛ける）になっていない。"], "viz": "<svg viewBox=\"0 0 340 136\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\">向きの反転を2回おこなう</text><text x=\"30\" y=\"42\" fill=\"#8892a4\" font-size=\"9\">1回目: −をかけて向きを反転</text><line x1=\"170\" y1=\"55\" x2=\"170\" y2=\"55\" stroke=\"#2a2f3f\"/><line x1=\"60\" y1=\"55\" x2=\"280\" y2=\"55\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><line x1=\"170\" y1=\"49\" x2=\"170\" y2=\"61\" stroke=\"#8892a4\"/><text x=\"170\" y=\"70\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">0</text><line x1=\"170\" y1=\"55\" x2=\"100\" y2=\"55\" stroke=\"#c47070\" stroke-width=\"2.2\"/><polygon points=\"100,55 110,50 110,60\" fill=\"#c47070\"/><text x=\"135\" y=\"49\" fill=\"#c47070\" font-size=\"9.5\" text-anchor=\"middle\">−4</text><text x=\"30\" y=\"96\" fill=\"#8892a4\" font-size=\"9\">2回目: もう一度−をかけて向きを反転</text><line x1=\"60\" y1=\"112\" x2=\"280\" y2=\"112\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><line x1=\"170\" y1=\"106\" x2=\"170\" y2=\"118\" stroke=\"#8892a4\"/><line x1=\"170\" y1=\"112\" x2=\"250\" y2=\"112\" stroke=\"#6ab08d\" stroke-width=\"2.2\"/><polygon points=\"250,112 240,107 240,117\" fill=\"#6ab08d\"/><text x=\"215\" y=\"128\" fill=\"#6ab08d\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">向きが戻り +16</text></svg>"}'),

  ('stats9-q04', '数学の部品箱',
   '「2x+1」という式のxに3を入れて計算すると、答えはいくつか。',
   NULL::text,
   '["7", "6", "8", "5"]',
   0,
   '[0]',
   'single',
   '{"asked": "文字式（xを使った式）に、具体的な数を入れて計算する練習。", "point": "xは「まだ数が決まっていない箱」。数を入れたら、あとはふつうの計算をするだけ。", "kid": "xは空っぽの箱のようなもの。ここに3を入れると「2×3+1」になる。あとはかけ算・たし算の順番どおりに計算すればいい。", "eg": "レシピの「卵×2個」の「2」の部分が空欄になっていて、そこに具体的な材料の個数を書き込むイメージ。xという空欄に3という数を書き込んだら、あとはレシピ（式）どおりに手順を進めるだけ。", "terms": [["文字式", "xやyなど、まだ決まっていない数を文字で表した式"], ["代入", "文字に具体的な数を入れること"]], "think": "「2x」は「2×x」の×を省略した書き方。だからx=3を入れると「2×3」になる。ここでかけ算とたし算が混ざっているときは、かけ算を先に計算するという算数のルールに従う。2×3=6を先に出してから、+1をして7。式の意味さえ分かれば、あとは普通の四則計算と同じ。", "calc": "式：  2x + 1　←　xの部分に3を入れる\n     2×3 + 1\n=     6  + 1\n=      7", "vs": "6は「2×3」だけ計算して+1を忘れた値。8は先に3+1を計算してから2を掛けてしまった（掛け算とたし算の順番を間違えた）値。5は2xを「2+x」と読み違えた値。式の形をそのまま数字に置き換えることが大事。", "why_asked": "統計の式（平均の式、分散の式など）はすべて「文字式に数字を当てはめて計算する」作業でできている。文字式を怖がらず数字を入れて計算する練習が、この先すべての公式の土台になる。", "usecase": "料金プランの計算式（基本料金+使用量×単価）、体重や身長から指標を出す計算式など、日常の「式に数を入れて答えを出す」場面すべて。", "opt": ["正解。xに3を入れると2×3+1=7。", "2×3=6の計算で止まり、+1をし忘れた値。", "3+1を先に計算してから2を掛けてしまった、計算順序を間違えた値。", "2xを「2+x」と読み違え、3+2=5としてしまった値。"], "viz": "<svg viewBox=\"0 0 340 95\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"18\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\">箱(x)に3を入れる</text><rect x=\"20\" y=\"40\" width=\"46\" height=\"34\" rx=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"43\" y=\"62\" fill=\"#60a5fa\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"600\">x</text><line x1=\"66\" y1=\"57\" x2=\"96\" y2=\"57\" stroke=\"#8892a4\"/><polygon points=\"96,57 88,53 88,61\" fill=\"#8892a4\"/><rect x=\"100\" y=\"40\" width=\"46\" height=\"34\" rx=\"4\" fill=\"#3b82f6\" opacity=\"0.75\"/><text x=\"123\" y=\"62\" fill=\"#e8eaf0\" font-size=\"15\" text-anchor=\"middle\" font-weight=\"600\">3</text><text x=\"200\" y=\"62\" fill=\"#e8eaf0\" font-size=\"13\" text-anchor=\"middle\">2×3+1 = 7</text></svg>"}'),

  ('stats9-q05', '数学の部品箱',
   '1辺が4cmの正方形の面積は何cm²か。',
   NULL::text,
   '["16", "8", "12", "32"]',
   0,
   '[0]',
   'single',
   '{"asked": "「2乗」が図形の面積とどうつながっているかを確かめる問題。", "point": "正方形の面積は「1辺×1辺」。同じ数を2回掛けることを「2乗」と呼ぶ。", "kid": "正方形は縦も横も同じ長さ。面積は「縦×横」で出すので、1辺が4なら4×4を計算すればよい。", "eg": "1マス1cm×1cmの方眼紙の上に、1辺4マスの正方形を描くと、中のマス目は縦4列×横4列で16マス。これがそのまま「4×4=16」の意味。", "terms": [["2乗", "同じ数を2回掛けること。4の2乗は4×4=16、書き方は4²"], ["面積", "図形の広さ。正方形なら1辺×1辺"]], "think": "正方形の面積は「縦×横」で求めるが、正方形は縦と横が同じ長さなので、結局「同じ数を2回掛ける」だけになる。これがまさに「2乗」という計算。だから2乗という計算には「正方形の面積を出している」という具体的なイメージを重ねられる。この後出てくる√（ルート）は、この逆再生（面積から1辺を求める）にあたる。", "calc": "1辺   4cm\n面積 = 4 × 4 = 16 cm²", "vs": "8は4を2倍しただけ（2乗になっていない）の値。12は4×3の計算間違い。32は16をさらに2倍した値。「2乗」と「2倍」は別の計算なので混同しないこと。", "why_asked": "このあと出てくる「分散」は、差を2乗した数の集まり。2乗を「正方形の面積」としてイメージできると、分散が表しているものが図形的にも実感しやすくなる。", "usecase": "面積の計算そのものに加え、ピタゴラスの定理（直角三角形の辺の関係）、分散・標準偏差の計算など、2乗はいたるところで使われる。", "opt": ["正解。4×4=16cm²。1辺×1辺が正方形の面積。", "4を2倍しただけの値。2乗（同じ数を2回掛ける）になっていない。", "4×3と掛け間違えた値。1辺の数を正しく2回使っていない。", "正しい面積16を、さらに2倍してしまった値。"], "viz": "<svg viewBox=\"0 0 340 130\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"18\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\">1辺4の正方形の面積</text><rect x=\"120\" y=\"30\" width=\"70\" height=\"70\" fill=\"#3b82f6\" opacity=\"0.35\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"155\" y=\"26\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">4</text><text x=\"112\" y=\"68\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">4</text><text x=\"155\" y=\"70\" fill=\"#e8eaf0\" font-size=\"14\" text-anchor=\"middle\" font-weight=\"600\">4×4=16</text><text x=\"155\" y=\"118\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">面積 = 1辺 × 1辺 = 4² = 16</text></svg>"}'),

  ('stats9-q06', '数学の部品箱',
   '面積が16cm²の正方形がある。1辺の長さは何cmか。',
   NULL::text,
   '["4", "8", "32", "256"]',
   0,
   '[0]',
   'single',
   '{"asked": "面積から1辺の長さを逆算する「√（ルート）」の考え方。", "point": "√16は「2乗すると16になる数」のこと。4×4=16なので√16=4。", "kid": "前の問題は「1辺4の正方形の面積は？」だった。今度はその逆で「面積16の正方形の1辺は？」を聞かれている。2乗の逆再生をするのが√（ルート）という記号。", "eg": "動画の「早送り」を戻すのが「巻き戻し」であるように、「2乗」を戻す（逆再生する）計算が√（ルート）。4を2乗すると16になったのだから、16を√で戻すと4に戻る。", "terms": [["√（ルート）", "2乗する前の数を求める記号。√16は「2乗すると16になる数」で答えは4"], ["2乗の逆再生", "√は2乗の計算を逆にたどる操作というイメージ"]], "think": "前問で「4×4=16」を確かめた。今度はその16だけが分かっていて、元の4を知りたい。これは「2乗を逆にたどる」作業で、記号では√16と書く。√16を計算するときは、いきなり公式に頼るより「2乗して16になる数は何か」を考えるほうが早い。4×4=16なので√16=4。", "calc": "面積 = 16 cm²　←　これは「1辺×1辺」の結果\n2乗して16になる数は？　→　4×4=16\n1辺 = √16 = 4 cm", "vs": "8は16を2で割った（半分にした）だけの値で、√の計算ではない。32・256は逆に、16をさらに2倍・2乗してしまった値。√は「割る」でも「掛ける」でもなく、「2乗する前の数を探す」逆再生の作業だと覚える。", "why_asked": "次のセットで出てくる標準偏差は「分散の√（ルート）」で求める。分散という2乗された数を、元の単位（点数など）に戻すために√を使う。この逆再生の感覚がないと、標準偏差の式の意味がつかめない。", "usecase": "標準偏差の計算、直角三角形の辺の長さ（三平方の定理）、図形の対角線の長さなど、2乗を戻す場面全般。", "opt": ["正解。4×4=16なので√16=4。1辺の長さは4cm。", "16を半分にしただけの値。√の計算（2乗する前の数を探す）になっていない。", "16を2倍にしてしまった値。√とは逆方向の計算をしている。", "16をさらに2乗してしまった値。√の意味とちょうど逆の操作をしている。"], "viz": "<svg viewBox=\"0 0 340 136\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"18\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\">面積16の正方形の1辺は？</text><rect x=\"120\" y=\"30\" width=\"70\" height=\"70\" fill=\"#3b82f6\" opacity=\"0.35\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"155\" y=\"70\" fill=\"#e8eaf0\" font-size=\"14\" text-anchor=\"middle\" font-weight=\"600\">面積 16</text><line x1=\"120\" y1=\"112\" x2=\"190\" y2=\"112\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><text x=\"155\" y=\"126\" fill=\"#6ab08d\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">1辺 = √16 = 4</text></svg>"}'),

  ('stats9-q07', '数学の部品箱',
   '5人のテストの合計点は310点だった。5人で均等に分けたときの1人あたりの点数（平均）はいくつか。',
   NULL::text,
   '["62", "310", "1550", "60"]',
   0,
   '[0]',
   'single',
   '{"asked": "「合計を人数で割る」という、平均のいちばん基本の計算。", "point": "平均は「合計 ÷ 人数」。310点を5人で均等に分けると1人62点。", "kid": "310点というのは5人ぶんの合計。これを5人で同じ量ずつ分けるには、310を5で割ればいい。310÷5=62。", "eg": "310個のアメを5人の子どもに同じ数ずつ配るとしたら、1人何個もらえるか。答えは310÷5=62個。テストの点数の平均も、これとまったく同じ「均等に配る」計算。", "terms": [["平均", "合計を人数（個数）で割った値。「均等に分けたらいくつか」を表す"], ["÷（割り算）", "合計をいくつかに均等に分ける計算"]], "think": "「平均」と聞くと難しく感じるが、やっていることは「合計を人数で割る」というシンプルな割り算。5人ぶんの点数を1つの山（合計310）と考えて、それを5人で同じ高さに分け直したときの高さが平均。分けたあとの1人分の量が62点なので、これが平均点になる。", "calc": "合計点  ÷  人数\n 310   ÷   5   =  62　←　1人あたり（平均）", "vs": "310は割り算をせず合計をそのまま答えてしまった値。1550は5を掛けてしまった値（割ると掛けるを逆にした）。60は310÷5の計算を大まかに丸めてしまった不正確な値。平均はきちんと310÷5=62まで計算する。", "why_asked": "平均は統計でいちばん最初に出てくる要約の数字で、この先の偏差・分散・標準偏差はすべて「平均との比較」から始まる。÷人数という手順を体に入れておくことが土台になる。", "usecase": "テストの平均点、家計の月平均支出、工場での1個あたりの平均加工時間など、「合計から1人分・1個分を出す」場面全般。", "opt": ["正解。310÷5=62。合計を人数で割ったものが平均。", "5人ぶんの合計をそのまま答えてしまった値。割り算をしていない。", "310に5を掛けてしまった値。割るところを掛けてしまった計算ミス。", "310÷5の計算を大まかに丸めた、不正確な値。"], "viz": "<svg viewBox=\"0 0 340 132\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\">合計310点を5人に均等配分</text><rect x=\"140\" y=\"24\" width=\"60\" height=\"20\" rx=\"3\" fill=\"#c9a04a\" opacity=\"0.6\"/><text x=\"170\" y=\"38\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\">合計 310</text><circle cx=\"50\" cy=\"90\" r=\"13\" fill=\"#3b82f6\" opacity=\"0.6\"/><text x=\"50\" y=\"94\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">62</text><circle cx=\"110\" cy=\"90\" r=\"13\" fill=\"#3b82f6\" opacity=\"0.6\"/><text x=\"110\" y=\"94\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">62</text><circle cx=\"170\" cy=\"90\" r=\"13\" fill=\"#3b82f6\" opacity=\"0.6\"/><text x=\"170\" y=\"94\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">62</text><circle cx=\"230\" cy=\"90\" r=\"13\" fill=\"#3b82f6\" opacity=\"0.6\"/><text x=\"230\" y=\"94\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">62</text><circle cx=\"290\" cy=\"90\" r=\"13\" fill=\"#3b82f6\" opacity=\"0.6\"/><text x=\"290\" y=\"94\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">62</text><text x=\"170\" y=\"120\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">310 ÷ 5 = 62（1人ぶん）</text></svg>"}'),

  ('stats9-q08', '数学の部品箱',
   '5人の点数を、1番目からx₁, x₂, x₃, x₄, x₅と名札を付けて呼ぶことにした。「3番目の人の点数」を指す書き方はどれか。',
   NULL::text,
   '["x₃", "x₁", "x₅", "x"]',
   0,
   '[0]',
   'single',
   '{"asked": "添字（右下の小さい数字）が「何番目か」を表す名札だという理解。", "point": "添字の数字は出席番号のようなもの。3番目の人はx₃。", "kid": "x₁, x₂, x₃…の右下の小さい数字は「出席番号」のようなもの。3番目の人ならx₃と呼ぶ。", "eg": "クラス名簿で「1番、2番、3番…」と出席番号を付けるのと同じ。x₃と書けば「xさんの中の3番の人」だと一目で分かる。番号を付けないと「x」とだけ書いても誰のことか分からない。", "terms": [["添字（そえじ）", "文字の右下に小さく書く数字。「何番目か」を区別する名札"], ["x₁, x₂, x₃…", "1番目、2番目、3番目…の値をまとめて呼ぶときの書き方"]], "think": "5人分の点数を1つずつ「56点さん」「58点さん」と呼ぶのは面倒なので、まとめてxという文字を使い、区別するために右下に番号（添字）を付ける。この番号は「何番目のデータか」を示すだけで、点数の大きさとは関係ない。3番目の人を指したいなら、その人の点数の大きさに関わらずx₃と書く。", "calc": "1番目の人 x₁ = 56点\n2番目の人 x₂ = 58点\n3番目の人 x₃ = 60点　←　これが「3番目」\n4番目の人 x₄ = 62点\n5番目の人 x₅ = 64点", "vs": "x₁は1番目、x₅は5番目を指しており、番号を読み違えている。添字なしの「x」は誰のことか特定できない、名札を付ける前の状態。", "why_asked": "次に出てくるΣ（シグマ）はx₁からx₅までを「全部」足すという意味の記号。全部を指すには、まず1つ1つに番号（添字）が付いていることが前提になる。添字の意味が分からないとΣの式が読めない。", "usecase": "名簿番号・座席番号のように「同じ種類のものを区別して呼ぶ」場面全般。統計・プログラミングでは、データの並び（リスト）の何番目かを指すときに必ず使う書き方。", "opt": ["正解。3番目の人を指す添字は3なので、x₃。", "1番目の人を指す書き方。番号を読み違えている。", "5番目（最後）の人を指す書き方。番号を読み違えている。", "添字がなく、5人のうちの誰を指しているか特定できない書き方。"], "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\">名簿の3番目 = x₃</text><rect x=\"30\" y=\"28\" width=\"280\" height=\"15\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"0.5\"/><text x=\"45\" y=\"39\" fill=\"#8892a4\" font-size=\"9.5\">x1</text><text x=\"290\" y=\"39\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"end\">56点</text><rect x=\"30\" y=\"46\" width=\"280\" height=\"15\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"0.5\"/><text x=\"45\" y=\"57\" fill=\"#8892a4\" font-size=\"9.5\">x2</text><text x=\"290\" y=\"57\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"end\">58点</text><rect x=\"30\" y=\"64\" width=\"280\" height=\"15\" rx=\"2\" fill=\"#3b82f6\" opacity=\"0.55\"/><text x=\"45\" y=\"75\" fill=\"#e8eaf0\" font-size=\"9.5\">x3</text><text x=\"290\" y=\"75\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"end\">60点</text><rect x=\"30\" y=\"82\" width=\"280\" height=\"15\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"0.5\"/><text x=\"45\" y=\"93\" fill=\"#8892a4\" font-size=\"9.5\">x4</text><text x=\"290\" y=\"93\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"end\">62点</text><rect x=\"30\" y=\"100\" width=\"280\" height=\"15\" rx=\"2\" fill=\"#2a2f3f\" opacity=\"0.5\"/><text x=\"45\" y=\"111\" fill=\"#8892a4\" font-size=\"9.5\">x5</text><text x=\"290\" y=\"111\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"end\">64点</text></svg>"}'),

  ('stats9-q09', '数学の部品箱',
   '5人の点数x₁からx₅までを全部足した式「x₁+x₂+x₃+x₄+x₅」を、記号を使って短く1つで書くとどれか。',
   NULL::text,
   '["Σxᵢ", "Πxᵢ", "√x", "x̄"]',
   0,
   '[0]',
   'single',
   '{"asked": "「全部足す」という作業を1つの記号にまとめた、Σ（シグマ）の意味。", "point": "Σは「ぜんぶ足す」を意味する記号。x₁+x₂+…+x₅はΣxᵢと1文字で書ける。", "kid": "x₁からx₅までを1つずつ足していく式は長くて書くのが大変。この「全部足す」という作業をまとめて表す記号がΣ（シグマ）。", "eg": "買い物のレシートに「りんご+みかん+バナナ+…」と全部書き出す代わりに、レシートの一番下に「合計」と1行で書くのと同じ。Σは、バラバラの値を全部合計した「合計」という1行の役割をする記号。", "terms": [["Σ（シグマ）", "「ぜんぶ足す」という意味の記号。Σxᵢはx₁からxₙまでを全部足すこと"], ["xᵢ", "i番目のxという意味。iにはx₁のときは1、x₅のときは5が入る"]], "think": "x₁+x₂+x₃+x₄+x₅という式は、人数が増えるほど長くなって書くのが大変になる。そこで「番号を1からnまで動かしながら全部足す」という作業を、Σというギリシャ文字1文字にまとめてしまう。Σxᵢと書けば「xᵢを、iを1から順番に動かしながら全部足しなさい」という指示になる。長い式を短く扱えるようにするための、いわば「省略記号」。", "calc": "x₁ + x₂ + x₃ + x₄ + x₅\n= 56 + 58 + 60 + 62 + 64\n= 300\nこれを1文字で書くと →  Σxᵢ = 300", "vs": "Π（パイ）は「ぜんぶ掛ける」を意味する別の記号で、足し算のΣとは役割が違う。√は2乗の逆再生の記号、x̄（エックスバー）は平均を表す記号で、どちらも「全部足す」という意味は持っていない。", "why_asked": "このあと平均や分散の式は、必ずΣを使って「x₁からxₙまでの合計」という形で書かれる。Σを「ぜんぶ足すの意味」と知っているだけで、式を見た瞬間の拒否反応がなくなる。", "usecase": "平均の式（Σxᵢ÷n）、分散の式（Σ(xᵢ−x̄)²÷n）など、統計の公式のほぼすべてにΣが登場する。", "opt": ["正解。Σは「ぜんぶ足す」という意味の記号。Σxᵢでx₁からx₅までの合計を表す。", "Πは「ぜんぶ掛ける」を意味する記号で、足し算ではなく掛け算を表す。", "√は2乗する前の数を求める記号で、足し算をまとめる記号ではない。", "x̄（エックスバー）は平均を表す記号で、合計をまとめる記号ではない。"], "viz": "<svg viewBox=\"0 0 340 105\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\">バラバラのxをΣで1つに集める</text><circle cx=\"40\" cy=\"30\" r=\"4\" fill=\"#60a5fa\"/><text x=\"55\" y=\"34\" fill=\"#8892a4\" font-size=\"9\">x1</text><circle cx=\"40\" cy=\"46\" r=\"4\" fill=\"#60a5fa\"/><text x=\"55\" y=\"50\" fill=\"#8892a4\" font-size=\"9\">x2</text><circle cx=\"40\" cy=\"62\" r=\"4\" fill=\"#60a5fa\"/><text x=\"55\" y=\"66\" fill=\"#8892a4\" font-size=\"9\">x3</text><circle cx=\"40\" cy=\"78\" r=\"4\" fill=\"#60a5fa\"/><text x=\"55\" y=\"82\" fill=\"#8892a4\" font-size=\"9\">x4</text><circle cx=\"40\" cy=\"94\" r=\"4\" fill=\"#60a5fa\"/><text x=\"55\" y=\"98\" fill=\"#8892a4\" font-size=\"9\">x5</text><line x1=\"70\" y1=\"30\" x2=\"150\" y2=\"70\" stroke=\"#8892a4\" stroke-width=\"1\"/><line x1=\"70\" y1=\"94\" x2=\"150\" y2=\"70\" stroke=\"#8892a4\" stroke-width=\"1\"/><rect x=\"155\" y=\"50\" width=\"70\" height=\"40\" rx=\"5\" fill=\"#3b82f6\" opacity=\"0.7\"/><text x=\"190\" y=\"75\" fill=\"#e8eaf0\" font-size=\"16\" text-anchor=\"middle\" font-weight=\"600\">Σ</text><text x=\"270\" y=\"75\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\">＝300</text></svg>"}'),

  ('stats9-q10', '数学の部品箱',
   '2を何回か掛け合わせて8にしたい。何回掛ければよいか。',
   NULL::text,
   '["3", "4", "2", "8"]',
   0,
   '[0]',
   'single',
   '{"asked": "log（ログ）が「何回掛けたら届くか」を求める記号だという理解。", "point": "2×2×2=8なので、2を3回掛けると8になる。この「3」がlog₂8の答え。", "kid": "2を1回掛けると2、2回掛けると4、3回掛けると8。「8にするには2を何回掛ければいいか」という質問への答えが3。", "eg": "ゲームのレベルアップで「経験値が2倍、2倍…」と増えていくとき、「目標の8倍にするには何回レベルアップすればいいか」を数えるのと同じ。2倍を3回繰り返すと8倍になる。", "terms": [["log（対数、ログ）", "「ある数を何回掛けたら目的の数に届くか」を求める計算・記号"], ["log₂8", "「2を何回掛けたら8になるか」という意味。答えは3"]], "think": "2×2=4、2×2×2=8というように、2を掛ける回数を1回ずつ増やしていくと、4、8、16…と数が階段状に増えていく。「8」という結果に対して「2を何回掛けたか」を逆にたどって答える計算がlog。log₂8と書けば「底（掛ける数）が2のとき、8に届くには何回か」という意味で、答えは3。深く公式を覚えなくても「何回掛けたら届くか」という素朴な問いだと分かれば怖くない。", "calc": "2 × 2 × 2 = 8　←　2を3回掛けた\nlog₂8 = 3　　←　「2を3回掛けたら8」という意味", "vs": "4は2×2×2×2=16まで数え間違えた回数、2は2×2=4で止めてしまった回数。8はlogの答えではなく、掛けた先の数（8）そのものをそのまま答えてしまっている。logが聞いているのは「回数」であって「結果の数」ではない。", "why_asked": "機械学習や検定の計算式にlogがよく登場するが、深い計算力より「何回掛けたら届くかを求める記号」という感覚があれば、式を見ても拒否反応が出ない。この2セットでは「読めて怖くない」ことがゴール。", "usecase": "データの桁数が大きく広がりすぎたときに「圧縮して見やすくする」変換（対数変換）、情報量やpH（酸性・アルカリ性の強さ）の表現など。", "opt": ["正解。2×2×2=8なので、2を3回掛けると8になる。log₂8=3。", "2×2×2×2=16まで数えてしまい、8ではなく16になる回数を答えている。", "2×2=4で止まってしまい、8まで届いていない回数を答えている。", "掛けた回数ではなく、目標の結果である「8」そのものを答えてしまっている。"], "viz": "<svg viewBox=\"0 0 340 136\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\">2を何回掛けたら8？</text><rect x=\"40\" y=\"75\" width=\"55\" height=\"20\" fill=\"#3b82f6\" opacity=\"0.6\"/><text x=\"67\" y=\"68\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">2</text><rect x=\"110\" y=\"55\" width=\"55\" height=\"40\" fill=\"#3b82f6\" opacity=\"0.6\"/><text x=\"137\" y=\"48\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">4</text><rect x=\"180\" y=\"35\" width=\"55\" height=\"60\" fill=\"#3b82f6\" opacity=\"0.6\"/><text x=\"207\" y=\"28\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\">8</text><line x1=\"40\" y1=\"95\" x2=\"270\" y2=\"95\" stroke=\"#2a2f3f\"/><text x=\"67\" y=\"108\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">1回</text><text x=\"137\" y=\"108\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">2回</text><text x=\"207\" y=\"108\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">3回</text><text x=\"170\" y=\"125\" fill=\"#6ab08d\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">log₂8 = 3</text></svg>"}'),

  ('stats9-q11', '数学の部品箱',
   'お金が「一瞬も休まず、なめらかに増え続ける」ような増え方をするとき、その増え方の速さを表す特別な数はおよそいくつか。',
   NULL::text,
   '["2.7", "3.14", "1.41", "10"]',
   0,
   '[0]',
   'single',
   '{"asked": "「なめらかに増え続ける」増え方を代表する特別な数（ネイピア数e）の存在を知る。", "point": "1年を細かく分けて利息を計算し続けると、増える倍率はある数（約2.72）に近づいていく。この数をeと呼ぶ。", "kid": "お金を「1年に1回」ではなく「半年ごと」「1か月ごと」…とどんどん細かく利息計算していくと、増える倍率はだんだんある1つの数に近づいていく。その数がだいたい2.72で、eと呼ぶ。", "eg": "蛇口をひねって水を入れるとき、「1秒ごとにドバッ」と入れるより「常にチョロチョロ流し続ける」ほうがなめらかに水位が上がる。eは、この「常にチョロチョロ」を数字にしたときの増え方の速さを表す定数。", "terms": [["e（ネイピア数）", "「なめらかに増え続ける」ときの増え方の速さを表す特別な数。およそ2.72"], ["連続的に増える", "1年に1回、1か月に1回…ではなく、絶え間なく増え続けること"]], "think": "利息の計算を「1年に1回」ではなく「1年を2回に分けて半分ずつ」「4回に分けて」…と細かくしていくと、最終的に増える倍率は少しずつ大きくなるが、無限に大きくなるわけではなく、ある数に近づいて止まる。この「行き着く先の数」がeで、およそ2.72。細かく分ければ分けるほど、増え方は「なめらか」になっていく。", "calc": "1回で計算:      (1+1/1)¹  = 2\n2回に分けて計算: (1+1/2)² = 2.25\n4回に分けて計算: (1+1/4)⁴ ≈ 2.44\n無限に細かく分ける → 2.72 に近づいて止まる（この数がe）", "vs": "3.14は円周率（円の直径と円周の関係を表す数）で、eとは別物。1.41は√2（正方形の対角線の比）に近い数。10は桁数の思い違い。eは「連続的な増え方」専用の定数として覚える。", "why_asked": "正規分布（ベル型の分布）の式や、なめらかな変化を表す式にeがよく登場する。計算できなくても、「なめらかに増え続けるときに出てくる約2.72という定数」というイメージだけで式への抵抗感が消える。", "usecase": "複利計算、人口やウイルスの感染者数のような「なめらかに増える」現象のモデル化、正規分布の式など。", "opt": ["正解。利息計算をどんどん細かくしていくと、増える倍率はおよそ2.72に近づく。この数がe。", "3.14は円周率。円の直径と円周の関係を表す別の数で、なめらかな増え方の定数ではない。", "1.41は√2に近い数（正方形の対角線の比）で、増え方の速さを表す定数ではない。", "10は桁の思い違い。増え方が近づく先の数はもっと小さく、およそ2.72。"], "viz": "<svg viewBox=\"0 0 340 134\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\">刻みを細かくすると値がある数に近づく</text><polyline points=\"30,95 90,80 150,60 210,45 270,36\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.6\"/><text x=\"270\" y=\"30\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">粗い刻み</text><path d=\"M30 95 C 110 60, 200 40, 300 33\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.8\"/><text x=\"300\" y=\"24\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"middle\">なめらか(e)</text><line x1=\"30\" y1=\"108\" x2=\"310\" y2=\"108\" stroke=\"#2a2f3f\"/><text x=\"170\" y=\"122\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">近づく先が e ≈ 2.72</text></svg>"}'),

  ('stats9-q12', '数学の部品箱',
   'ある坂道は、横に10m進むごとに高さが2m上がる。この坂の傾き（勾配）はいくつか。',
   NULL::text,
   '["0.2", "2", "10", "0.02"]',
   0,
   '[0]',
   'single',
   '{"asked": "「傾き」が縦の変化と横の変化の比だという理解。機械学習の「勾配降下法」の勾配もこれと同じ考え方。", "point": "傾き＝縦の変化 ÷ 横の変化。2m÷10m=0.2。", "kid": "坂道の「きつさ」は、横にどれだけ進んだら、縦にどれだけ上がるかで決まる。横10mで縦2m上がるなら、傾きは2÷10=0.2。", "eg": "階段の1段の「蹴上げ（縦の高さ）」と「踏み面（横の奥行き）」の比のようなもの。横に対して縦がどれだけ急に上がるかを1つの数で表したのが傾き。", "terms": [["傾き（勾配）", "横に1進んだときに縦がどれだけ変化するかを表す数。縦の変化÷横の変化"], ["勾配降下法", "機械学習でよく出てくる言葉。坂を下るように、傾きを頼りに答えに近づいていく計算方法"]], "think": "坂の「きつさ」を「高さだけ」で語ると、坂の長さによって印象が変わってしまい不公平になる。だから「横にどれだけ進んだら、縦にどれだけ上がるか」の比で表す。横10mに対して縦2m上がるなら、傾きは2÷10=0.2。この0.2という数が大きいほど急な坂、小さいほど緩やかな坂ということになる。この「縦の変化÷横の変化」という考え方が、微分やAIの学習で出てくる「勾配」の入口になる。", "calc": "縦の変化(高さ)  ÷  横の変化(距離)\n     2m        ÷      10m      = 0.2", "vs": "「2」は縦の変化（高さ）だけを答えてしまった値。「10」は横の変化（距離）だけを答えてしまった値。「0.02」は2÷10の計算はできているが、位（けた）を1つ間違えて余計に10で割ってしまった値。傾きは必ず「縦÷横」の順で計算し、位もそろえる。", "why_asked": "機械学習の「勾配降下法」でいう勾配は、この傾きと同じ考え方の延長。急な坂ほど一気に下れて、緩やかな坂ほど少しずつしか下れない、というイメージが、AIがどう学習していくかの直感につながる。", "usecase": "道路標識の勾配表示、屋根の傾斜、グラフの変化の速さの読み取り、AIの学習アルゴリズム（勾配降下法）の基礎イメージ。", "opt": ["正解。縦の変化2m÷横の変化10m=0.2。これが坂の傾き。", "縦の変化（高さ）である2をそのまま答えてしまい、横の変化で割っていない値。", "横の変化（距離）である10をそのまま答えてしまい、傾きの計算になっていない値。", "2÷10の計算の途中で位を1つ間違え、余計に10で割ってしまった値。"], "viz": "<svg viewBox=\"0 0 340 132\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"16\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\">坂のきつさ＝傾き</text><line x1=\"40\" y1=\"105\" x2=\"270\" y2=\"45\" stroke=\"#60a5fa\" stroke-width=\"2\"/><line x1=\"40\" y1=\"105\" x2=\"270\" y2=\"105\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><text x=\"155\" y=\"118\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">横 10m</text><line x1=\"270\" y1=\"105\" x2=\"270\" y2=\"45\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><text x=\"292\" y=\"78\" fill=\"#8892a4\" font-size=\"9.5\">縦 2m</text><text x=\"170\" y=\"34\" fill=\"#6ab08d\" font-size=\"12\" text-anchor=\"middle\" font-weight=\"600\">傾き = 2 ÷ 10 = 0.2</text></svg>"}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'stats-basics'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
